"""Deterministic SNMP test dataset for the actsnmp interop lab.

This module is the single source of truth for the data served by both
interop agents:

  * net-snmp snmpd  -> via the pass_persist script actsnmp_pass.py
  * snmpsim         -> via snmprec files generated by gen_snmprec.py

so a walk of the shared subtree must give byte-identical results from both
agents and from actsnmp agent.

All OIDs live below netSnmpPlaypen (1.3.6.1.4.1.8072.9999), which is reserved
for experiments and not used by any stock snmpd module.

  BASE = 1.3.6.1.4.1.8072.9999.1       shared dataset ("public")
  PATH = 1.3.6.1.4.1.8072.9999.2       snmpsim-only pathological dataset

Value representation: (oid_tuple, type, value) with type one of

  INTEGER    int  (Integer32)
  OCTETS     bytes
  OID        tuple of int
  IPADDR     bytes (len 4)
  COUNTER32  int
  GAUGE32    int  (Gauge32 / Unsigned32, same BER tag 0x42)
  TIMETICKS  int
  OPAQUE     bytes (raw content of the Opaque OCTET STRING)
  COUNTER64  int
  NULL       None (snmpsim only)
  NOSUCHOBJECT / NOSUCHINSTANCE / ENDOFMIBVIEW  None (snmpsim only)

Nothing in here may depend on time, randomness or the host.
"""

BASE = (1, 3, 6, 1, 4, 1, 8072, 9999, 1)
PATH = (1, 3, 6, 1, 4, 1, 8072, 9999, 2)

# number of rows in the tables
TABLE_ROWS = 300       # BASE.10  (7 columns, column 7 sparse)
STRTABLE_ROWS = 20     # BASE.11  (string indexed)
BIGTABLE_ROWS = 2000   # BASE.12  (2 columns)


def _pattern(n, alphabet=b"0123456789abcdefghijklmnopqrstuvwxyz"):
    """Printable deterministic pattern of length n."""
    return bytes(alphabet[i % len(alphabet)] for i in range(n))


def _binpattern(n):
    return bytes(i % 256 for i in range(n))


# ---------------------------------------------------------------- scalars ---

INTEGERS = [
    0, 1, -1, 127, 128, -128, -129, 255, 256, 32767, 32768, -32768, -32769,
    8388607, 8388608, -8388608, -8388609, 2147483647, -2147483648,
]

OCTET_STRINGS = [
    b"Hello, SNMP!",                                  # .1 printable
    b"",                                              # .2 empty
    _binpattern(256),                                 # .3 all byte values 00..ff
    "räksmörgås".encode("utf-8"),      # .4 UTF-8 (non-ASCII bytes)
    b'quote " and backslash \\ chars',                # .5 printable w/ specials
    b"tab\there\nnewline",                            # .6 control chars
    _pattern(127),                                    # .7 len 127 (short BER len)
    _pattern(128),                                    # .8 len 128 (0x81 0x80)
    _pattern(255),                                    # .9 len 255 (0x81 0xff)
    _pattern(256),                                    # .10 len 256 (0x82 0x01 0x00)
    _pattern(1000),                                   # .11 1000 bytes printable
    _binpattern(1024),                                # .12 1024 bytes binary
    _pattern(4000),                                   # .13 4000 bytes (> 1500 MTU)
    b"\x00",                                          # .14 single NUL
    b"\xff\xff\xff\xff",                              # .15 all ones
    b" leading and trailing spaces ",                 # .16
]

OIDS = [
    (0, 0),                                           # .1 zeroDotZero
    (1, 3, 6, 1, 4, 1, 8072, 3, 2, 10),               # .2 typical sysObjectID
    (1, 3, 6, 1, 4, 1, 4294967295, 0),                # .3 max sub-identifier
    (2, 999, 1),                                      # .4 first arcs 2.999 -> 0x88 0x37
    (1, 3, 6, 1, 2, 1, 1, 1, 0),                      # .5 sysDescr.0
    BASE + (3, 127, 128, 16383, 16384, 2097151, 2097152,
            268435455, 268435456),                    # .6 base-128 boundaries
    (1, 3) + tuple(range(1, 127)),                    # .7 128 sub-identifiers (max)
    (1, 3),                                           # .8 two arcs only
]

IPADDRS = [
    bytes([0, 0, 0, 0]),
    bytes([127, 0, 0, 1]),
    bytes([192, 0, 2, 1]),
    bytes([255, 255, 255, 255]),
]

COUNTER32S = [0, 1, 2147483647, 2147483648, 4294967295]
GAUGE32S = [0, 1, 2147483648, 4294967295]
TIMETICKS = [0, 100, 8640000, 4294967295]
COUNTER64S = [0, 1, 4294967295, 4294967296, 9223372036854775807,
              9223372036854775808, 18446744073709551615]
OPAQUES = [
    bytes.fromhex("deadbeef"),                        # .1 arbitrary bytes
    bytes.fromhex("9f7804" "3f800000"),               # .2 net-snmp Opaque Float 1.0
    bytes.fromhex("9f7a01" "2a"),                     # .3 net-snmp Opaque Int64 42
]

# --------------------------------------------------------------- writable ---
# BASE.20.<n>.0 - writable scalars.  snmpd: pass_persist "set"; snmpsim:
# writecache variation.  Values reset to these on every agent (re)start.
#   n: (type, initial value, settable?, constraint description)
WRITABLE = [
    (1, "INTEGER", 42, True),
    (2, "OCTETS", b"initial", True),
    (3, "OID", (1, 3, 6, 1), True),
    (4, "IPADDR", bytes([192, 0, 2, 1]), True),
    (5, "GAUGE32", 0, True),
    (6, "TIMETICKS", 0, True),
    (7, "INTEGER", 7, False),        # read-only: SET -> notWritable (snmpd)
    (8, "INTEGER", 50, True),        # range 0..100 enforced by snmpd only (wrongValue)
]
WRITABLE_RANGE = {8: (0, 100)}


def _scalar_group(group, typ, values):
    return [(BASE + (group, i + 1, 0), typ, v) for i, v in enumerate(values)]


def table_rows():
    """BASE.10 = actsnmpTable, BASE.10.1 = entry, columns 1..7, index = row"""
    recs = []
    t = BASE + (10, 1)
    for i in range(1, TABLE_ROWS + 1):
        recs.append((t + (1, i), "INTEGER", i))
        recs.append((t + (2, i), "OCTETS", b"row-%04d" % i))
        recs.append((t + (3, i), "COUNTER64", (i * 1000000007) % (1 << 64)))
        recs.append((t + (4, i), "IPADDR", bytes([10, (i >> 16) & 255, (i >> 8) & 255, i & 255])))
        recs.append((t + (5, i), "GAUGE32", i * 7))
        recs.append((t + (6, i), "OID", t + (1, i)))
        if i % 3 == 0:  # sparse column: only every third row
            recs.append((t + (7, i), "INTEGER", -i))
    return recs


STRTABLE_NAMES = ["eth%d" % i for i in range(10)] + ["ge-0/0/%d" % i for i in range(5)] + \
    ["lo", "lo0", "mgmt0", "x", "a-long-interface-name-for-index-tests"]


def strtable_rows():
    """BASE.11 = string indexed table; index = length-prefixed OCTET STRING
    (non-IMPLIED) i.e. <len>.<c1>...<cn>.  Columns: 1 name, 2 mtu, 3 admin."""
    recs = []
    t = BASE + (11, 1)
    for n, name in enumerate(STRTABLE_NAMES):
        b = name.encode()
        idx = (len(b),) + tuple(b)
        recs.append((t + (1,) + idx, "OCTETS", b))
        recs.append((t + (2,) + idx, "INTEGER", 1500 + n))
        recs.append((t + (3,) + idx, "INTEGER", 1 if n % 2 == 0 else 2))
    return recs


def bigtable_rows():
    """BASE.12 = big table for multi-PDU bulkwalks: 2 columns x 2000 rows."""
    recs = []
    t = BASE + (12, 1)
    for i in range(1, BIGTABLE_ROWS + 1):
        recs.append((t + (1, i), "INTEGER", i))
        recs.append((t + (2, i), "OCTETS", b"big-%05d" % i))
    return recs


def writable_records():
    return [(BASE + (20, n, 0), typ, val) for (n, typ, val, _rw) in WRITABLE]


def records():
    """The complete shared dataset, sorted in lexicographic OID order."""
    recs = []
    recs += _scalar_group(1, "INTEGER", INTEGERS)
    recs += _scalar_group(2, "OCTETS", OCTET_STRINGS)
    recs += _scalar_group(3, "OID", OIDS)
    recs += _scalar_group(4, "IPADDR", IPADDRS)
    recs += _scalar_group(5, "COUNTER32", COUNTER32S)
    recs += _scalar_group(6, "GAUGE32", GAUGE32S)
    recs += _scalar_group(7, "TIMETICKS", TIMETICKS)
    recs += _scalar_group(8, "COUNTER64", COUNTER64S)
    recs += _scalar_group(9, "OPAQUE", OPAQUES)
    recs += table_rows()
    recs += strtable_rows()
    recs += bigtable_rows()
    recs += writable_records()
    recs.sort(key=lambda r: r[0])
    return recs


def oidstr(oid):
    return ".".join(str(x) for x in oid)


# ------------------------------------------------- canonical text format ---
# See interop/README.md, "Canonical output". Ground truth for the
# expected/*.txt files.

def _hex(b):
    return " ".join("%02X" % x for x in b)


def canon_value(typ, val):
    if typ == "INTEGER":
        return "INTEGER: %d" % val
    if typ == "OCTETS":
        if all(0x20 <= x <= 0x7E for x in val):
            return 'STRING: "%s"' % val.decode("ascii").replace("\\", "\\\\").replace('"', '\\"')
        return "Hex-STRING: " + _hex(val)
    if typ == "OID":
        return "OID: ." + oidstr(val)
    if typ == "IPADDR":
        return "IpAddress: %d.%d.%d.%d" % tuple(val)
    if typ == "COUNTER32":
        return "Counter32: %d" % val
    if typ == "GAUGE32":
        return "Gauge32: %d" % val
    if typ == "TIMETICKS":
        return "Timeticks: %d" % val
    if typ == "COUNTER64":
        return "Counter64: %d" % val
    if typ == "OPAQUE":
        return "Opaque: " + (_hex(val) if val else '""')
    if typ == "NULL":
        return "NULL"
    if typ == "NOSUCHOBJECT":
        return "noSuchObject"
    if typ == "NOSUCHINSTANCE":
        return "noSuchInstance"
    if typ == "ENDOFMIBVIEW":
        return "endOfMibView"
    raise ValueError(typ)


def canon_line(oid, typ, val):
    return ".%s = %s" % (oidstr(oid), canon_value(typ, val))


if __name__ == "__main__":
    import sys
    n = 0
    for oid, typ, val in records():
        n += 1
    sys.stdout.write("%d records\n" % n)
